[CmdletBinding()]
param([string]$RepoRoot=(Get-Location).Path)
$ErrorActionPreference='Stop'
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path
if(!(Test-Path -LiteralPath (Join-Path $RepoRoot 'GuideVault.sln'))){throw 'Run from the GuideVault repository root.'}
function HashText([string]$s){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$patch=@'
[{"path":"src/Guidevault.Web/GuidevaultDocumentIndex.cs","before":"fe68cafe7ad0267e3c153c3296cfb1a12856f663281a627cb8cd9046cc4d5b06","after":"a21f4715a76edc8b3c05c46f4c0d6b6642eb102b4d6af48b525b4f805649edd6","payload":""}]
'@ | ConvertFrom-Json
$pending=@()
foreach($p in $patch){
    $path=Join-Path $RepoRoot $p.path
    $exists=Test-Path -LiteralPath $path -PathType Leaf
    $raw=if($exists){[IO.File]::ReadAllText($path).Replace("`r`n","`n")}else{''}
    $hash=HashText $raw
    $target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p.payload))
    if((HashText $target) -ne $p.after){throw "Payload integrity check failed: $($p.path)"}
    if($exists -and $hash -eq $p.after){continue}
    if(($exists -and ($null -eq $p.before -or $hash -ne $p.before)) -or (!$exists -and $null -ne $p.before)){throw "Unexpected source revision: $($p.path). No files changed. Install on Magazine Metadata Enrichment v1 (Phase 4.6.2)."}
    $pending+=@{name=$p.path;path=$path;target=$target;exists=$exists}
}
$paths=@($patch | ForEach-Object {$_.path})
$backup=Join-Path $RepoRoot ('.guidevault-patch-backups/magazine-article-identity-v1-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
foreach($p in $pending){if($p.exists){$dest=Join-Path $backup $p.name;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null;Copy-Item -LiteralPath $p.path -Destination $dest}}
try{
    foreach($p in $pending){
        $bom=$false
        if($p.exists){$bytes=[IO.File]::ReadAllBytes($p.path);$bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191}
        [IO.File]::WriteAllText($p.path,$p.target,[Text.UTF8Encoding]::new($bom))
        if([IO.File]::ReadAllText($p.path) -cne $p.target){throw "Write verification failed: $($p.name)"}
    }
}catch{foreach($p in $pending){if($p.exists){Copy-Item -LiteralPath (Join-Path $backup $p.name) -Destination $p.path -Force}else{Remove-Item -LiteralPath $p.path -ErrorAction SilentlyContinue}};throw}
foreach($path in $paths){
    $tracked=& git -C $RepoRoot ls-files -- $path
    if($LASTEXITCODE -ne 0){throw "Git ls-files failed: $path"}
    if($tracked){
        & git -C $RepoRoot update-index --no-assume-unchanged -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear assume-unchanged: $path"}
        & git -C $RepoRoot update-index --no-skip-worktree -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear skip-worktree: $path"}
    }
    & git -C $RepoRoot add -f -- $path
    if($LASTEXITCODE -ne 0){throw "Git staging failed: $path"}
    & git -C $RepoRoot diff --exit-code -- $path
    if($LASTEXITCODE -ne 0){throw "Working tree differs from staged source: $path"}
}
Write-Host "Backup (if changes made): $backup"
Write-Host 'GuideVault Magazine Article Identity v1 installed and staged. Existing UI and indexes retained.' -ForegroundColor Green
& git -C $RepoRoot diff --cached --stat
